static IEnumerable ConveyTo(Visual load, Visual target) {
    load.PushRoutingTarget(target);
    if (!TargetIsReachable(load, target)) {
        throw new Exception("Target cannot be reached: load=" + load.Name + " target=" + target.FullName);
    }
    ReleaseLoad(load);
    yield return WaitForLoadToArrive(load, target, SetDispatchOutFalse);
}

static bool TargetIsReachable(Visual load, Visual target) {
    if (load == null || target == null) {
        return false;
    }

    var conv = load.CurrentStation.Visual;

    if (conv != null && conv.Parent != null && (conv.Parent is ConveyorVisual || conv.Parent.HasCustomProperty("IsMotorOn"))) {
        conv = conv.Parent;
    }

    if (target.Parent == conv || target == conv) return true;

    if (target.HasCustomProperty("IsStation")) {
        target = target.Parent as Visual;
    }

    var routing = new ConnectedRoutingDijkstra(conv, target);
    return routing.FirstTransfer != null;
}

public static void SetDispatchOut(Visual load, bool enabled) {
    if (enabled) {
        load.RemoveCustomProperty("DispatchOutEnabled");
    } else {
        load.AddCustomProperty("DispatchOutEnabled", false, "");
    }
}

static void ReleaseLoad(Visual load) {
    var station = load.CurrentStation.Visual;

    var _load = load as PhysicsObject;
    SetKinematic(_load, false);

    if (station != null && station.TransferStateEnabled) {
        SetDispatchOut(load, true);
        Transfer.Dispatch(station);
    }
}

