public static Visual GetTarget( Visual load ) {
    var target = load.CurrentRoutingTarget;
    if (target == null) { return null; }
    target = load.HasCustomProperty("_CurrentRoutingTarget")
        ? load.GetCustomPropertyValue<VisualReference>("_CurrentRoutingTarget").Visual
        : target;
    load.RemoveCustomProperty("_CurrentRoutingTarget");
    return (target.Parent is ConveyorVisual) ? target.Parent : target;
}

public static bool IsTargetInRoute( Visual _from, Visual target, Visual match ) {
    if (target == null) { return false; }
    if (ReferenceEquals(_from, target)) {
        return ReferenceEquals(target, match);
    }

    var routing = new ConnectedRoutingDijkstra( _from, target );
    var route   = routing.Route;

    if (route == null || route.Count == 0) {
        throw new Exception("Target cannot be reached: from=" + _from.Name + " target=" + target.FullName);
    }

