void StopInfeed( FeedClass infeed ){
    var controller = infeed.Controller;
    if ( infeed.Conv == BoxVisual.Parent ){
        controller = _PrevController;
    }
    if ( controller != null ){
        controller.SetCustomPropertyValue( "ReleaseEnabled", false );
        var infeedConv = controller.Parent as ConveyorVisual;
        infeedConv.IsMotorOn = false;
    }    
}

void ReleaseInfeed( FeedClass infeed ){
    var controller = infeed.Controller;
    if ( infeed.Conv == BoxVisual.Parent ){
        controller = _PrevController;
    }
    if ( controller != null ){
        controller.SetCustomPropertyValue( "ReleaseEnabled", true );
        var infeedConv = controller.Parent as ConveyorVisual;
        infeedConv.IsMotorOn = true;
    } 
}

